  public static Sensor.StopEvent.Builder mergeStopEvent(
      Sensor.StopEvent dst, Sensor.StopEvent src) {
    Sensor.StopEvent.Builder builder = dst.toBuilder();
    if (dst.getReason().isEmpty()) {
      builder.setReason(src.getReason());
    }
    return builder;
  }

  public static Sensor.SensorEvent.Builder mergeSensorEvent(
      Sensor.SensorEvent dst, Sensor.SensorEvent src) {
    Sensor.SensorEvent.Builder builder = dst.toBuilder();
    if (dst.getEventId().isEmpty()) {
      builder.setEventId(src.getEventId());
    }
    if (dst.getTimestampMs() == 0) {
      builder.setTimestampMs(src.getTimestampMs());
    }
    if (dst.getEventTypeValue() == 0) {
      builder.setEventTypeValue(src.getEventTypeValue());
    }
    if (dst.getSessionId().isEmpty()) {
      builder.setSessionId(src.getSessionId());
    }
    if (dst.getWorkingDirectory().isEmpty()) {
      builder.setWorkingDirectory(src.getWorkingDirectory());
    }
    if (dst.getAgentId().isEmpty()) {
      builder.setAgentId(src.getAgentId());
    }
    if (dst.getParentAgentId().isEmpty()) {
      builder.setParentAgentId(src.getParentAgentId());
    }
    if (dst.getDepth() == 0) {
      builder.setDepth(src.getDepth());
    }
    if (dst.getSensorNodeId().isEmpty()) {
      builder.setSensorNodeId(src.getSensorNodeId());
    }
    if (dst.getUsername().isEmpty()) {
      builder.setUsername(src.getUsername());
    }
    if (dst.getSensorTypeValue() == 0) {
      builder.setSensorTypeValue(src.getSensorTypeValue());
    }
    if (dst.getTranscriptPath().isEmpty()) {
      builder.setTranscriptPath(src.getTranscriptPath());
    }
    if (dst.getHookPhaseValue() == 0) {
      builder.setHookPhaseValue(src.getHookPhaseValue());
    }
    if (dst.getPayloadCase() == Sensor.SensorEvent.PayloadCase.PAYLOAD_NOT_SET) {
      switch (src.getPayloadCase()) {
        case SESSION:
          builder.setSession(src.getSession());
          break;
        case TOOL_USE:
          builder.setToolUse(src.getToolUse());
          break;
        case SUBAGENT:
          builder.setSubagent(src.getSubagent());
          break;
        case PROMPT:
          builder.setPrompt(src.getPrompt());
          break;
        case STOP:
          builder.setStop(src.getStop());
          break;
        default:
          break;
      }
    }
    return builder;
  }

  public static Sensor.AgenticCodeEventBus.Builder mergeAgenticCodeEventBus(
      Sensor.AgenticCodeEventBus dst, Sensor.AgenticCodeEventBus src) {
    Sensor.AgenticCodeEventBus.Builder builder = dst.toBuilder();
    if (dst.getClaimsMap().isEmpty()) {
      builder.putAllClaims(src.getClaimsMap());
    }
    if (!dst.hasEventStream() && src.hasEventStream()) {
      builder.setEventStream(src.getEventStream());
    } else if (dst.hasEventStream() && src.hasEventStream()) {
      builder.setEventStream(mergeSensorEvent(dst.getEventStream(), src.getEventStream()).build());
    }
    return builder;
  }

  public static Sensor.TopicPublishReceipt.Builder mergeTopicPublishReceipt(
      Sensor.TopicPublishReceipt dst, Sensor.TopicPublishReceipt src) {
    Sensor.TopicPublishReceipt.Builder builder = dst.toBuilder();
    if (!dst.getPublished()) {
      builder.setPublished(src.getPublished());
    }
    return builder;
  }

