  public static Map<String, String> agenticCodeEventBusToEnvVar(Sensor.AgenticCodeEventBus msg) {
    Map<String, String> result = new HashMap<>();
    if (msg.hasEventStream()) {
      result.putAll(sensorEventToEnvVar(msg.getEventStream()));
    }
    return result;
  }

  public static Sensor.AgenticCodeEventBus.Builder agenticCodeEventBusFromEnvVar(
      Map<String, String> env) {
    Sensor.AgenticCodeEventBus.Builder builder = Sensor.AgenticCodeEventBus.newBuilder();
    {
      var sub = sensorEventFromEnvVar(env).build();
      if (!sub.equals(sub.getDefaultInstanceForType())) {
        builder.setEventStream(sub);
      }
    }
    return builder;
  }

